css:
.btn1 {
  color: black;
  background-color: white;
  border: solid wheat 2px;
  border-radius: 9px;
  font-size: 19px;
  padding: 12px;
  box-shadow: inset 0 0 4px black;
  font-weight: 500;
  transition: 400ms;
}
.btn1:hover {
  transition: 400ms;
  box-shadow: inset 0 0 6px black, 0 0 10px wheat;
}
.btn1:active {
  transition: 50ms;
  box-shadow: inset 0 0 0px black, 0 0 10px wheat;
}
